drop view if exists public.registry_relationship_consolidation_queue; create view public.registry_relationship_consolidation_queue with (security_invoker = true) as with classified as ( select k.*, count(*) over (partition by source_entity_type, source_comparison_key, target_entity_type, target_comparison_key, relationship_type, coalesce(relationship_role, ''))::integer as duplicate_group_size from public.registry_relationship_duplicate_keys k where relationship_status <> 'archived' ) select relationship_id, source_entity_type, source_entity_id, source_slug, source_comparison_key, target_entity_type, target_entity_id, target_slug, target_comparison_key, relationship_type, relationship_role, relationship_status, review_status, public_safe, plain_reason, evidence_count, case when source_entity_id is null or target_entity_id is null then 'resolve_endpoints' when evidence_count = 0 then 'attach_evidence' when nullif(btrim(plain_reason), '') is null then 'add_plain_reason' when review_status in ('unreviewed','pending_review','disputed') then 'review_required' when review_status = 'approved' and public_safe = false then 'publication_review' else 'ready' end as consolidation_state, relationship_type in ('features','featured_on','collaboration','popular_track') as vocabulary_supported, duplicate_group_size, duplicate_group_size > 1 as duplicate_candidate from classified;;
